func TestLoadEnvTokenWinsOverKeychain(t *testing.T) {
	keyring.MockInit()
	configPath := filepath.Join(t.TempDir(), "config.toml")
	keychainToken := "keychain-token-secret"
	envToken := "env-token-secret"

	if err := keyring.Set(DefaultKeychainService, DefaultKeychainAccount, keychainToken); err != nil {
		t.Fatalf("set keychain token: %v", err)
	}
	if err := os.WriteFile(configPath, []byte("keychain_service = \""+DefaultKeychainService+"\"\nkeychain_account = \""+DefaultKeychainAccount+"\"\n"), 0o600); err != nil {
		t.Fatalf("write config: %v", err)
	}
	t.Setenv("STRADDLE_TOKEN", envToken)

	cfg, err := Load(configPath)
	if err != nil {
		t.Fatalf("load config: %v", err)
	}
	if got := cfg.AuthHeader(); got != "Bearer "+envToken {
		t.Fatalf("AuthHeader = %q, want env token", got)
	}
	if got := cfg.AuthSource; got != "env:STRADDLE_TOKEN" {
		t.Fatalf("AuthSource = %q, want env source", got)
	}
}

