func TestSaveKeychainTokenAbortsWhenExistingKeychainStateIsUnreadable(t *testing.T) {
	oldGet := keyringGet
	oldSet := keyringSet
	oldDelete := keyringDelete
	t.Cleanup(func() {
		keyringGet = oldGet
		keyringSet = oldSet
		keyringDelete = oldDelete
	})

	rawErr := errors.New("raw OS keychain read failure detail")
	setCalled := false
	keyringGet = func(service, account string) (string, error) {
		return "", rawErr
	}
	keyringSet = func(service, account, password string) error {
		setCalled = true
		return nil
	}
	keyringDelete = func(service, account string) error {
		return nil
	}

	token := "unreadable-prior-token-secret"
	cfg := &Config{Path: filepath.Join(t.TempDir(), "config.toml")}

	err := cfg.SaveKeychainToken(token)
	if err == nil {
		t.Fatalf("SaveKeychainToken should fail when prior keychain state is unreadable")
	}
	if got := err.Error(); got != "keychain_unavailable" {
		t.Fatalf("SaveKeychainToken error = %q, want stable keychain_unavailable", got)
	}
	if strings.Contains(err.Error(), rawErr.Error()) || strings.Contains(err.Error(), token) {
		t.Fatalf("SaveKeychainToken error leaked raw detail or token: %v", err)
	}
	if setCalled {
		t.Fatalf("SaveKeychainToken should not call keyring Set when prior keychain state is unreadable")
	}
	if cfg.UsesKeychain() || cfg.StraddleToken != "" || cfg.AuthHeaderVal != "" || cfg.AccessToken != "" {
		t.Fatalf("failed keychain save should not set in-memory auth metadata: %#v", cfg)
	}
}

